import org.junit.Test;

import java.io.IOException;
import java.io.StringReader;

import static org.junit.Assert.*;

public class JjFillTokenTests {

    private SimpleCharStream input_stream;
    private XPathParserTokenManager tokenManager;

    @Before
    public void setUp() throws IOException {
        StringReader reader = new StringReader("test");
        input_stream = new SimpleCharStream(reader);
        tokenManager = new XPathParserTokenManager(input_stream);
        // Initialize stream buffer and position to prevent ArrayIndexOutOfBoundsException
        // when jjFillToken accesses input_stream methods like getEndLine().
        input_stream.BeginToken();
        input_stream.readChar();
    }

    @Test
    public void testJjFillTokenWithLiteralImage() {
        // jjstrLiteralImages[6] corresponds to "/" (ASCII 47, octal 57)
        tokenManager.jjmatchedKind = 6; 

        Token token = tokenManager.jjFillToken();

        assertNotNull(token);
        assertEquals(6, token.kind);
        assertEquals("/", token.image);
    }

    @Test
    public void testJjFillTokenWithStreamImage() {
        // Use a kind that maps to null in jjstrLiteralImages (indices 1-5 are null)
        // to force jjFillToken to retrieve the image from the input stream.
        tokenManager.jjmatchedKind = 1; 

        // Manually setup the buffer state to simulate a matched string "test"
        input_stream.tokenBegin = 0;
        input_stream.buffer = "test".toCharArray();
        input_stream.bufpos = 3;

        Token token = tokenManager.jjFillToken();

        assertNotNull(token);
        assertEquals(1, token.kind);
        assertEquals("test", token.image);
    }

    @Test
    public void testJjFillTokenPositionInformation() throws IOException {
        // Use a literal image kind
        tokenManager.jjmatchedKind = 6; // "/"

        StringReader multiLineReader = new StringReader("a\nb");
        SimpleCharStream stream = new SimpleCharStream(multiLineReader);
        XPathParserTokenManager manager = new XPathParserTokenManager(stream);

        // Initialize stream state by reading characters to update line/column counters
        stream.BeginToken(); // Reads 'a' (Line 1, Col 1)
        stream.readChar();   // Reads '\n' (Line 1, Col 2 -> transitions to Line 2, Col 1)
        stream.readChar();   // Reads 'b' (Line 2, Col 1)

        Token token = manager.jjFillToken();

        assertNotNull(token);
        // Verify line and column match the state established by the stream
        // tokenBegin is 0 (default), so BeginLine is Line 1.
        // bufpos is 2 (char 'b'), so EndLine is Line 2.
        assertEquals(1, token.beginLine);
        assertEquals(1, token.beginColumn);
        assertEquals(2, token.endLine);
        assertEquals(1, token.endColumn);
    }

    @Test
    public void testJjFillTokenEmptyStringLiteral() {
        // jjstrLiteralImages[0] is ""
        tokenManager.jjmatchedKind = 0;

        Token token = tokenManager.jjFillToken();

        assertNotNull(token);
        assertEquals(0, token.kind);
        assertEquals("", token.image);
    }

    @Test
    public void testJjFillTokenImageFromBufferNullCheck() {
        // Ensure that when jjstrLiteralImages is null for the kind, 
        // jjFillToken constructs the image from the stream buffer.
        // Index 2 is null in the provided jjstrLiteralImages array.
        tokenManager.jjmatchedKind = 2; 
        String testString = "variable";

        input_stream.tokenBegin = 0;
        input_stream.buffer = testString.toCharArray();
        input_stream.bufpos = testString.length() - 1;

        Token token = tokenManager.jjFillToken();

        assertNotNull("Token should not be null", token);
        assertEquals("Kind should match", 2, token.kind);
        assertEquals("Image should match buffer content", testString, token.image);
    }
}

